#pragma once

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <string>
#include <vector>
#include <unordered_map>
#include <optional>
#include <algorithm>

namespace ptv {

// Lightweight mission/objective schema local to this task
struct ObjectiveDef {
    std::string id;            // e.g., "defend_reactors"
    std::string type;          // e.g., "defend|escort|cleanse|disable|rescue|defeat"
    int target_count{1};       // count-based objectives (kills, rescues, pylons, etc.)
};

struct ChallengeDef {
    std::string id;            // optional challenge id
    std::string rule;          // free-form rule id (e.g., "no_damage", "time_under")
    float threshold{0.0f};
};

struct DifficultyTier {
    std::string id;            // "easy|normal|hard|legendary" (free-form)
    float ai_scale{1.0f};      // used by AI packs to scale aggression/spawns via tags
    float spawn_multiplier{1.0f};
    float score_multiplier{1.0f};
};

struct MissionDef {
    std::string id;
    std::vector<std::string> scenes;                 // ordered scene ids for travel
    std::vector<ObjectiveDef> objectives;            // linear for MVP; branches in future
    std::vector<ChallengeDef> challenges;            // optional
    std::vector<DifficultyTier> tiers;               // difficulty options
    int base_reward_xp{0};                           // baseline XP before multipliers
};

struct MedalThresholds {
    // per-mission thresholds (seconds for time trials, or score numbers)
    // map: mission_id -> { bronze, silver, gold }
    struct Trio { float bronze{0}, silver{0}, gold{0}; };
    std::unordered_map<std::string, Trio> by_mission;
};

struct ObjectiveProgress {
    int current{0};
    int target{1};
    bool completed{false};
};

struct MissionRuntimeState {
    bool has_selection{false};
    std::string selected_mission_id;
    std::string selected_difficulty{"normal"};
    std::size_t objective_index{0};
    std::unordered_map<std::string, ObjectiveProgress> objective_progress; // by objective id
    float elapsed_s{0.0f};
    bool in_progress{false};
    bool finished{false};
    bool failed{false};
    int score{0};
    std::optional<std::string> medal; // "bronze|silver|gold"
};

// Local helper utilities (declarations)
namespace mission_util {

inline void push_tag(World& w, std::uint32_t e, const std::string& tag) {
    if (!w.valid(e)) return;
    if (!w.has<CTag>(e)) {
        w.emplace_or_replace<CTag>(e, CTag{});
    }
    auto& tags = w.get<CTag>(e).tags;
    tags.emplace_back(tag);
}

inline std::string make_tag(const std::string& prefix, const nlohmann::json& payload) {
    return prefix + payload.dump();
}

// Parse helpers
void parse_missions(const nlohmann::json& j, std::unordered_map<std::string, MissionDef>& out);
MedalThresholds parse_medal_thresholds(const nlohmann::json& j);

// Runtime helpers
void reset_runtime_for_mission(const MissionDef& def, MissionRuntimeState& rt);
void tick_objectives_from_tags(World& w, MissionRuntimeState& rt, const MissionDef& def, const std::string& objectiveProgressPrefix, std::uint32_t selfEntity);
void maybe_award_medal_and_persist(World& w, std::uint32_t e, const MissionDef& def, MissionRuntimeState& rt, const MedalThresholds& thresholds,
                                   const std::string& saveSectionPushPrefix, const std::string& saveRequestPrefix,
                                   const std::string& uiToastPrefix, const std::string& missionCompletePrefix);

// UI helpers
void ensure_wrist_page_registered(World& w, std::uint32_t e, const std::string& uiPageRegisterPrefix);
void update_wrist_status(World& w, std::uint32_t e, const MissionDef* def, const MissionRuntimeState& rt, const std::string& uiToastPrefix, float toastCooldownReset);

} // namespace mission_util

} // namespace ptv

#include "mission_shared.h"

#include <cstddef>

namespace ptv { namespace mission_util {

static ObjectiveDef parse_objective(const nlohmann::json& j) {
    ObjectiveDef o;
    if (j.is_object()) {
        o.id = j.value("id", std::string{});
        o.type = j.value("type", std::string{"generic"});
        o.target_count = j.value("target_count", 1);
    }
    return o;
}

static DifficultyTier parse_tier(const nlohmann::json& j) {
    DifficultyTier t;
    if (j.is_object()) {
        t.id = j.value("id", std::string{"normal"});
        t.ai_scale = j.value("ai_scale", 1.0f);
        t.spawn_multiplier = j.value("spawn_multiplier", 1.0f);
        t.score_multiplier = j.value("score_multiplier", 1.0f);
    }
    return t;
}

void parse_missions(const nlohmann::json& j, std::unordered_map<std::string, MissionDef>& out) {
    out.clear();
    if (!j.is_array()) return;
    for (const auto& m : j) {
        if (!m.is_object()) continue;
        MissionDef def;
        def.id = m.value("id", std::string{});
        def.base_reward_xp = m.value("base_reward_xp", 0);
        if (m.contains("scenes") && m["scenes"].is_array()) {
            for (const auto& s : m["scenes"]) def.scenes.emplace_back(s.get<std::string>());
        }
        if (m.contains("objectives") && m["objectives"].is_array()) {
            for (const auto& o : m["objectives"]) def.objectives.emplace_back(parse_objective(o));
        }
        if (m.contains("challenges") && m["challenges"].is_array()) {
            for (const auto& c : m["challenges"]) {
                if (!c.is_object()) continue;
                ChallengeDef ch; ch.id = c.value("id", std::string{}); ch.rule = c.value("rule", std::string{}); ch.threshold = c.value("threshold", 0.0f);
                def.challenges.emplace_back(std::move(ch));
            }
        }
        if (m.contains("difficulty_tiers") && m["difficulty_tiers"].is_array()) {
            for (const auto& t : m["difficulty_tiers"]) def.tiers.emplace_back(parse_tier(t));
        }
        if (!def.id.empty()) out[def.id] = std::move(def);
    }
}

MedalThresholds parse_medal_thresholds(const nlohmann::json& j) {
    MedalThresholds mt;
    if (!j.is_object()) return mt;
    for (auto it = j.begin(); it != j.end(); ++it) {
        const std::string mid = it.key();
        MedalThresholds::Trio trio{};
        if (it.value().is_object()) {
            trio.bronze = it.value().value("bronze", 0.0f);
            trio.silver = it.value().value("silver", 0.0f);
            trio.gold   = it.value().value("gold",   0.0f);
        }
        mt.by_mission[mid] = trio;
    }
    return mt;
}

void reset_runtime_for_mission(const MissionDef& def, MissionRuntimeState& rt) {
    rt.objective_index = 0;
    rt.in_progress = false;
    rt.finished = false;
    rt.failed = false;
    rt.elapsed_s = 0.0f;
    rt.score = 0;
    rt.medal.reset();
    rt.objective_progress.clear();
    for (const auto& o : def.objectives) {
        rt.objective_progress[o.id] = ObjectiveProgress{0, std::max(1, o.target_count), false};
    }
}

}} // namespace ptv::mission_util

#include "mission_shared.h"

#include <entt/entt.hpp>

namespace ptv { namespace mission_util {

// Consumes objective progress tags from any entity, shaped as:
//   objective.progress:{"id":"<objective_id>", "delta":1, "state":"update|complete|fail"}
// After consuming, the string is erased from the source entity's CTag.
void tick_objectives_from_tags(World& w, MissionRuntimeState& rt, const MissionDef& def, const std::string& objectiveProgressPrefix, std::uint32_t selfEntity) {
    auto& reg = w.registry();
    auto view = reg.view<CTag>();
    for (auto ent : view) {
        auto& tags = view.get<CTag>(ent).tags;
        for (auto it = tags.begin(); it != tags.end(); ) {
            const std::string& s = *it;
            if (s.rfind(objectiveProgressPrefix, 0) == 0) {
                auto payload = nlohmann::json::parse(s.substr(objectiveProgressPrefix.size()), nullptr, false);
                if (payload.is_object()) {
                    const std::string oid = payload.value("id", std::string{});
                    const int delta = payload.value("delta", 0);
                    const std::string state = payload.value("state", std::string{"update"});
                    auto itp = rt.objective_progress.find(oid);
                    if (itp != rt.objective_progress.end()) {
                        auto& pr = itp->second;
                        if (state == "fail") {
                            rt.failed = true;
                        } else {
                            if (delta != 0) pr.current = std::max(0, pr.current + delta);
                            if (state == "complete" || pr.current >= pr.target) {
                                pr.current = pr.target;
                                pr.completed = true;
                            }
                        }
                        // Advance if current objective matches and is completed
                        if (!rt.failed && rt.objective_index < def.objectives.size()) {
                            const auto& cur = def.objectives[rt.objective_index];
                            if (cur.id == oid && pr.completed) {
                                rt.objective_index++;
                                // lightweight score increment per objective
                                rt.score += 100;
                                // Inform HUD via toast on our own entity
                                nlohmann::json j; j["text"] = std::string("Objective Complete: ") + oid; j["style"] = "success";
                                push_tag(w, selfEntity, make_tag("ui.toast:", j));
                            }
                            if (rt.objective_index >= def.objectives.size()) {
                                rt.finished = true;
                                rt.in_progress = false;
                            }
                        }
                    }
                }
                it = tags.erase(it);
            } else {
                ++it;
            }
        }
    }
}

}} // namespace ptv::mission_util

#include "mission_shared.h"

namespace ptv { namespace mission_util {

static std::optional<std::string> eval_medal(const std::string& missionId, float elapsedS, int score, const MedalThresholds& t) {
    auto it = t.by_mission.find(missionId);
    if (it == t.by_mission.end()) return std::nullopt;
    const auto& trio = it->second;
    // Heuristic: if thresholds are all >0, treat as time trial (lower is better). Otherwise treat as score (higher is better).
    const bool isTime = (trio.gold > 0.0f && trio.silver > 0.0f && trio.bronze > 0.0f);
    if (isTime) {
        if (elapsedS <= trio.gold)   return std::optional<std::string>{"gold"};
        if (elapsedS <= trio.silver) return std::optional<std::string>{"silver"};
        if (elapsedS <= trio.bronze) return std::optional<std::string>{"bronze"};
    } else {
        if (score >= (int)trio.gold)   return std::optional<std::string>{"gold"};
        if (score >= (int)trio.silver) return std::optional<std::string>{"silver"};
        if (score >= (int)trio.bronze) return std::optional<std::string>{"bronze"};
    }
    return std::nullopt;
}

void maybe_award_medal_and_persist(World& w, std::uint32_t e, const MissionDef& def, MissionRuntimeState& rt, const MedalThresholds& thresholds,
                                   const std::string& saveSectionPushPrefix, const std::string& saveRequestPrefix,
                                   const std::string& uiToastPrefix, const std::string& missionCompletePrefix) {
    if (!rt.finished || rt.medal.has_value()) return;

    auto medal = eval_medal(def.id, rt.elapsed_s, rt.score, thresholds);
    if (medal.has_value()) rt.medal = medal;

    // Persist completion + medal to Save system via tag protocol from dependency
    nlohmann::json savePayload;
    savePayload["section"] = "mission";
    savePayload["data"] = {
        {"mission_id", def.id},
        {"difficulty", rt.selected_difficulty},
        {"elapsed_s", rt.elapsed_s},
        {"score", rt.score},
        {"medal", rt.medal.value_or("")}
    };
    push_tag(w, e, make_tag(saveSectionPushPrefix, savePayload));

    // Also publish mission.complete for consumers (progression)
    nlohmann::json mc; mc["id"] = def.id; mc["difficulty"] = rt.selected_difficulty; mc["medal"] = rt.medal.value_or("");
    push_tag(w, e, make_tag(missionCompletePrefix, mc));

    // Request save
    nlohmann::json req; req["reason"] = "mission_complete"; req["immediate"] = true;
    push_tag(w, e, make_tag(saveRequestPrefix, req));

    // Toast
    nlohmann::json toast; toast["text"] = std::string("Mission Complete: ") + def.id + (rt.medal ? std::string(" — ") + *rt.medal + " medal" : std::string("")); toast["style"] = "success";
    push_tag(w, e, make_tag(uiToastPrefix, toast));
}

}} // namespace ptv::mission_util

#include "mission_shared.h"

namespace ptv { namespace mission_util {

void ensure_wrist_page_registered(World& w, std::uint32_t e, const std::string& uiPageRegisterPrefix) {
    // Idempotent: the HUD module deduplicates by id; we can push once on attach.
    nlohmann::json j; j["id"] = "mission_log"; j["title"] = "Missions"; j["order"] = 5;
    push_tag(w, e, make_tag(uiPageRegisterPrefix, j));
}

void update_wrist_status(World& w, std::uint32_t e, const MissionDef* def, const MissionRuntimeState& rt, const std::string& uiToastPrefix, float toastCooldownReset) {
    (void)toastCooldownReset; // reserved for future throttling
    if (!def) return;
    // Minimal HUD pulse on state transitions is driven elsewhere; here we can expose quick hints when selection happens.
    if (rt.has_selection && !rt.in_progress && !rt.finished) {
        nlohmann::json j; j["text"] = std::string("Selected: ") + def->id + " (" + rt.selected_difficulty + ") — Approach portal to deploy."; j["style"] = "info";
        push_tag(w, e, make_tag(uiToastPrefix, j));
    }
}

}} // namespace ptv::mission_util

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <entt/entt.hpp>
#include <string>
#include <unordered_map>
#include <optional>

#include "mission_shared.h"

namespace ptv {

class MissionSystemMechanic : public IMechanic {
public:
    void on_attach(World& world, std::uint32_t entity, const nlohmann::json& params) override {
        self_ = entity;
        // Dependency contracts (prefixes) from completed tasks
        ui_page_register_prefix_ = "ui.page.register:";   // from hud_and_wrist_menu
        ui_toast_prefix_ = "ui.toast:";                   // from hud_and_wrist_menu
        save_section_push_prefix_ = "save.section.push:"; // from save_persistence
        save_request_prefix_ = "save.request:";           // from save_persistence
        mission_complete_prefix_ = "mission.complete:";   // consumed by save_persistence/progression
        objective_progress_prefix_ = "objective.progress:"; // generic objective updates
        portal_travel_request_prefix_ = "portal.travel.request:"; // exposed for portal_travel module
        ai_difficulty_prefix_ = "ai.difficulty.profile:"; // hint to AI packs

        // Parse mission DB and medal thresholds from binding params
        if (params.contains("missions")) {
            mission_util::parse_missions(params.at("missions"), missions_);
        }
        if (params.contains("medal_thresholds")) {
            thresholds_ = mission_util::parse_medal_thresholds(params.at("medal_thresholds"));
        }

        // Register wrist page with HUD
        mission_util::ensure_wrist_page_registered(world, entity, ui_page_register_prefix_);

        // Optional: preselect a mission via params
        pending_select_id_ = params.value("preselect_mission_id", std::string{});
        pending_difficulty_ = params.value("preselect_difficulty", std::string{"normal"});
        if (!pending_select_id_.empty()) want_confirm_ = true; // auto-confirm in tests if preselected
    }

    void on_update(World& world, std::uint32_t entity, float dt) override {
        if (entity != self_) self_ = entity; // safety

        // Read per-frame control intents from our own CMechanicBinding entry params_json
        read_binding_params(world, entity);

        // Handle a new selection/confirmation
        handle_selection_and_launch(world, entity);

        // If a mission is running, tick timer and collect objective updates from tags
        if (rt_.in_progress && !rt_.finished && !rt_.failed) {
            rt_.elapsed_s += dt;
            const auto* def = get_current_def();
            if (def) {
                mission_util::tick_objectives_from_tags(world, rt_, *def, objective_progress_prefix_, self_);
            }
        }

        // If finished, evaluate medal and persist
        if (rt_.finished) {
            const auto* def = get_current_def();
            if (def) {
                mission_util::maybe_award_medal_and_persist(world, entity, *def, rt_, thresholds_,
                    save_section_push_prefix_, save_request_prefix_, ui_toast_prefix_, mission_complete_prefix_);
            }
        }

        // Opportunistic UI hinting
        mission_util::update_wrist_status(world, entity, get_current_def(), rt_, ui_toast_prefix_, 2.0f);
    }

    void on_detach(World&, std::uint32_t) override {}

    std::string id() const override { return "generated.mission_system"; }

private:
    // Read intents from our binding entry if present.
    void read_binding_params(World& world, std::uint32_t entity) {
        pending_select_id_.clear();
        // We allow tests/other modules to drive this via binding params OR via tags on this entity
        if (world.has<CMechanicBinding>(entity)) {
            const auto& mb = world.get<CMechanicBinding>(entity);
            for (const auto& entry : mb.entries) {
                if (entry.id == id() || entry.builtin_id == id()) {
                    auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
                    if (!j.is_object()) continue;
                    if (j.contains("select_mission_id")) {
                        pending_select_id_ = j.value("select_mission_id", std::string{});
                    }
                    if (j.contains("difficulty")) {
                        pending_difficulty_ = j.value("difficulty", std::string{"normal"});
                    }
                    want_confirm_ = j.value("confirm", want_confirm_);
                    portal_activated_ = j.value("portal_activated", portal_activated_);
                    // Objective synthetic injection for tests
                    if (j.contains("objective_progress")) {
                        auto pj = j.at("objective_progress");
                        if (pj.is_object()) {
                            nlohmann::json m; m["id"] = pj.value("id", ""); m["delta"] = pj.value("delta", 0); m["state"] = pj.value("state", "update");
                            mission_util::push_tag(world, entity, mission_util::make_tag(objective_progress_prefix_, m));
                        }
                    }
                }
            }
        }
        // Also allow external console to poke via tags: mission.select:{id, difficulty, confirm:true}
        if (world.has<CTag>(entity)) {
            auto& tags = world.get<CTag>(entity).tags;
            for (auto it = tags.begin(); it != tags.end(); ) {
                const std::string& s = *it;
                const std::string selectPrefix = "mission.select:";
                const std::string confirmPrefix = "mission.confirm:";
                const std::string portalPrefix = "portal.activated:";
                if (s.rfind(selectPrefix, 0) == 0) {
                    auto j = nlohmann::json::parse(s.substr(selectPrefix.size()), nullptr, false);
                    if (j.is_object()) {
                        pending_select_id_ = j.value("id", pending_select_id_);
                        pending_difficulty_ = j.value("difficulty", pending_difficulty_);
                    }
                    it = tags.erase(it);
                    continue;
                } else if (s.rfind(confirmPrefix, 0) == 0) {
                    want_confirm_ = true; it = tags.erase(it); continue;
                } else if (s.rfind(portalPrefix, 0) == 0) {
                    portal_activated_ = true; it = tags.erase(it); continue;
                } else {
                    ++it;
                }
            }
        }
    }

    void handle_selection_and_launch(World& world, std::uint32_t entity) {
        // Selection phase
        if (!pending_select_id_.empty()) {
            auto it = missions_.find(pending_select_id_);
            if (it != missions_.end()) {
                current_mission_id_ = pending_select_id_;
                rt_.has_selection = true;
                rt_.selected_mission_id = current_mission_id_;
                if (!pending_difficulty_.empty()) rt_.selected_difficulty = pending_difficulty_;
                mission_util::reset_runtime_for_mission(it->second, rt_);
                // AI scaling hint for other systems
                nlohmann::json dif; dif["tier"] = rt_.selected_difficulty; dif["scale"] = tier_ai_scale(it->second, rt_.selected_difficulty);
                mission_util::push_tag(world, entity, mission_util::make_tag(ai_difficulty_prefix_, dif));
                // Toast
                nlohmann::json t; t["text"] = std::string("Mission Selected: ") + current_mission_id_ + " (" + rt_.selected_difficulty + ")"; t["style"] = "info";
                mission_util::push_tag(world, entity, mission_util::make_tag(ui_toast_prefix_, t));
            }
            pending_select_id_.clear();
        }
        // Launch once confirmed and portal is activated
        if (rt_.has_selection && want_confirm_ && portal_activated_ && !rt_.in_progress) {
            const MissionDef* def = get_current_def();
            if (def) {
                // Ask portal system to begin travel; if portal module isn't present yet, tests still observe our intent via tag
                nlohmann::json travel; travel["mission_id"] = def->id; travel["difficulty"] = rt_.selected_difficulty; travel["scenes"] = def->scenes;
                mission_util::push_tag(world, entity, mission_util::make_tag(portal_travel_request_prefix_, travel));
                // Start runtime timer immediately (MVP)
                rt_.in_progress = true;
                rt_.elapsed_s = 0.0f;
                want_confirm_ = false;
                portal_activated_ = false;
                // Toast
                nlohmann::json t; t["text"] = std::string("Deploying: ") + def->id; t["style"] = "info";
                mission_util::push_tag(world, entity, mission_util::make_tag(ui_toast_prefix_, t));
            }
        }
    }

    const MissionDef* get_current_def() const {
        auto it = missions_.find(current_mission_id_);
        if (it == missions_.end()) return nullptr;
        return &it->second;
    }

    float tier_ai_scale(const MissionDef& def, const std::string& tierId) const {
        for (const auto& t : def.tiers) if (t.id == tierId) return t.ai_scale;
        return 1.0f;
    }

private:
    std::uint32_t self_{0};

    // Protocol prefixes
    std::string ui_page_register_prefix_;
    std::string ui_toast_prefix_;
    std::string save_section_push_prefix_;
    std::string save_request_prefix_;
    std::string mission_complete_prefix_;
    std::string objective_progress_prefix_;
    std::string portal_travel_request_prefix_;
    std::string ai_difficulty_prefix_;

    std::unordered_map<std::string, MissionDef> missions_;
    MedalThresholds thresholds_{};

    // Selection/launch intents
    std::string pending_select_id_;
    std::string pending_difficulty_{"normal"};
    bool want_confirm_{false};
    bool portal_activated_{false};

    // Active mission runtime
    std::string current_mission_id_;
    MissionRuntimeState rt_{};
};

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.mission_system", ptv::MissionSystemMechanic)

Mission System Tag Protocol (MVP)

Inputs this mechanic consumes (push as CTag strings on the Mission System entity):
- mission.select:{"id":"<mission_id>","difficulty":"easy|normal|hard"}
- mission.confirm:{}
- portal.activated:{}
- objective.progress:{"id":"<objective_id>","delta":1,"state":"update|complete|fail"}

Additionally, you can drive via binding params on the same entity:
{
  "select_mission_id":"zero_g_flight_gauntlet",
  "difficulty":"normal",
  "confirm":true,
  "portal_activated":true,
  "objective_progress":{"id":"gate_3","delta":1,"state":"update"}
}

Outputs this mechanic publishes:
- ui.page.register:{"id":"mission_log","title":"Missions","order":5}
- ui.toast:{...}                      // HUD/Wrist menu displays
- portal.travel.request:{"mission_id":"..","difficulty":"..","scenes":["scene_a",...]}
- ai.difficulty.profile:{"tier":"normal","scale":1.0}
- mission.complete:{"id":"..","difficulty":"..","medal":"gold|silver|bronze|"}
- save.section.push:{"section":"mission","data":{...}}
- save.request:{"reason":"mission_complete","immediate":true}

Medals:
- medal_thresholds in mechanic params can be time (lower better) or score (higher better). Time thresholds should fill bronze/silver/gold with seconds. For score mode, use numbers.

Notes:
- Objective chains are linear in MVP. Branches/retries can be emulated by posting objective.progress for different ids.
- Difficulty scaling is advisory via ai.difficulty.profile tag; AI packs may consume this to scale spawns.
